import { selectDriverCandidates } from '../src/driver-assignment/driver-candidate-selector'

const driver = (id: string, name: string, latitude: number, longitude: number, status: 'Disponible' | 'En viaje' = 'Disponible') => ({
  id,
  name,
  phone: '0000-0000',
  vehicle: 'Vehículo de prueba',
  plate: 'TEST-001',
  route: 'Sin viaje activo',
  status,
  latitude,
  longitude,
})

describe('driver candidate selector', () => {
  it('prefers an available driver in the same H3 cell', () => {
    const result = selectDriverCandidates({
      origin: { latitude: 12.1159, longitude: -86.2478 },
      drivers: [
        driver('near', 'Near', 12.11591, -86.24781),
        driver('far', 'Far', 12.118, -86.246),
      ],
      liveLocations: new Map([
        ['Near', { latitude: 12.11591, longitude: -86.24781, updatedAt: Date.now() }],
        ['Far', { latitude: 12.118, longitude: -86.246, updatedAt: Date.now() }],
      ]),
    })

    expect(result.usedFallback).toBe(false)
    expect(result.candidates.map((candidate) => candidate.driver.id)).toEqual(['near', 'far'])
  })

  it('does not use stale GPS to rank candidates', () => {
    const result = selectDriverCandidates({
      origin: { latitude: 12.1159, longitude: -86.2478 },
      drivers: [driver('old', 'Old', 12.1159, -86.2478)],
      liveLocations: new Map([
        ['Old', { latitude: 12.1159, longitude: -86.2478, updatedAt: Date.now() - 121_000 }],
      ]),
    })

    expect(result.usedFallback).toBe(true)
    expect(result.candidates.map((candidate) => candidate.driver.id)).toEqual(['old'])
    expect(result.candidates[0].ring).toBeNull()
  })

  it('filters unavailable drivers before spatial ranking', () => {
    const result = selectDriverCandidates({
      origin: { latitude: 12.1159, longitude: -86.2478 },
      drivers: [
        driver('busy', 'Busy', 12.11591, -86.24781, 'En viaje'),
        driver('free', 'Free', 12.14, -86.22),
      ],
      liveLocations: new Map([
        ['Busy', { latitude: 12.11591, longitude: -86.24781, updatedAt: Date.now() }],
        ['Free', { latitude: 12.14, longitude: -86.22, updatedAt: Date.now() }],
      ]),
    })

    expect(result.candidates.map((candidate) => candidate.driver.id)).toEqual(['free'])
  })
})
